import catalog from "./data/catalog.json" with { type: "json" };

export function catalogSummary() {
  const displays = Object.values(catalog.providers).map((provider) => provider.display).join(",");
  const aliases = catalog.providers.beta.models.flatMap((model) => model.aliases).join("|");
  const meta = Object.keys(catalog.providers.beta.metadata).join(",");
  const leaf = catalog.deep.level0.level1.level2.level3.level4.level5.level6.level7.level8.level9.level10.level11.level12.level13.level14.level15.level16.level17.level18.level19.level20.level21.level22.level23.level24.level25.level26.level27.level28.level29.level30.level31.level32.level33.level34.level35.level36.level37.level38.level39.level40.level41.level42.level43.level44.level45.level46.level47.level48.level49.level50.level51.level52.level53.level54.level55.level56.level57.level58.level59.level60.level61.level62.level63.level64.level65.level66.level67.level68.level69.level70.level71.level72.level73.level74.level75.level76.level77.level78.level79.leaf;
  return [displays, aliases, meta, catalog.defaults.fallback === null, leaf].join(";");
}
